// Oeste PageTitle — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/page-title

export function PageTitle({ title, meta }) {
  return (
    <div className="flex flex-col gap-2">
      <h1 className="m-0 text-[var(--type-ptitle-size)] leading-[var(--type-ptitle-leading)] tracking-[var(--type-ptitle-tracking)] text-[var(--color-ink)] [font-weight:var(--type-ptitle-weight)]">{title}</h1>
      {meta && <p className="m-0 text-[var(--type-meta-size)] leading-[var(--type-meta-leading)] text-[var(--color-muted)] [font-weight:var(--type-meta-weight)]">{meta}</p>}
    </div>
  );
}
